def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a


def gcd_all(xs):
    g = 0
    for x in xs:
        g = gcd(g, x)
    return g

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for q in range(p * p, n + 1, p):
                is_prime[q] = False
        p += 1
    return [i for i in range(n + 1) if is_prime[i]]

def factorise(n):
    out = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            out.append(d)
            n //= d
        d += 1
    if n > 1:
        out.append(n)
    return out
